-- Students of session 2026-2027 (783 rows). E-mail of an existing student is kept.
-- Generated by scripts/import-dining-sheet.js from sheet 2026-27. Safe to run twice.

on conflict (enrollment_no) do update set
  name = excluded.name, house = excluded.house, room_no = excluded.room_no,
  course = excluded.course, remarks = excluded.remarks, session = excluded.session,
  dining_from = excluded.dining_from;
